use std::{
    fs::{self, OpenOptions},
    io::{self, Write},
    path::Path,
    sync::OnceLock,
};

use gmod::{gmod13_close, gmod13_open, lua::State, lua_function, lua_string};

static SEED: OnceLock<String> = OnceLock::new();

const CLIENT_PATH: &str = "prot/embedded_router.lua";
const BUNDLE: &str = concat!(
    "-- Generated by gmsv_prot.\nlocal router = (function()\n",
    include_str!("../addon/lua/prot/router.lua"),
    "\nend)()\nlocal install = (function()\n",
    include_str!("../addon/lua/prot/transparent.lua"),
    "\nend)()\ninstall(router)\nreturn router\n",
);

const LEGACY_ENTRY: &str = r#"-- Generated by gmsv_prot.
if not ProtNet then
    if SERVER then
        require("prot")
        assert(ProtNative.Install())
    else
        include("prot/embedded_router.lua")
    end
end
return ProtNet
"#;

fn session_seed() -> Result<&'static str, getrandom::Error> {
    if let Some(seed) = SEED.get() {
        return Ok(seed);
    }

    let mut bytes = [0_u8; 16];
    getrandom::fill(&mut bytes)?;

    let seed = bytes.iter().map(|byte| format!("{byte:02x}")).collect();
    Ok(SEED.get_or_init(|| seed))
}

#[lua_function]
unsafe fn seed(lua: State) -> i32 {
    match session_seed() {
        Ok(seed) => {
            lua.push_string(seed);
            1
        }
        Err(_) => {
            lua.push_nil();
            lua.push_string("prot: OS random source unavailable");
            2
        }
    }
}

fn publish_asset(path: &Path, contents: &str, replace: bool) -> io::Result<()> {
    match fs::read(path) {
        Ok(previous) if !replace || previous == contents.as_bytes() => return Ok(()),
        Ok(_) => {}
        Err(error) if error.kind() == io::ErrorKind::NotFound => {}
        Err(error) => return Err(error),
    }

    let temp = path.with_extension(format!("{}.tmp", std::process::id()));
    let mut file = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&temp)?;
    let written = file.write_all(contents.as_bytes());
    drop(file);
    let result = written.and_then(|()| {
        if replace {
            fs::rename(&temp, path)
        } else {
            match fs::hard_link(&temp, path) {
                Err(error) if error.kind() == io::ErrorKind::AlreadyExists => Ok(()),
                result => result,
            }
        }
    });
    if !replace || result.is_err() {
        let _ = fs::remove_file(&temp);
    }
    result
}

fn install_assets() -> io::Result<()> {
    let game = Path::new("garrysmod");
    if !game.join("gameinfo.txt").is_file() {
        return Err(io::Error::new(
            io::ErrorKind::NotFound,
            "start the server from the directory containing garrysmod/gameinfo.txt",
        ));
    }

    let lua = game.join("lua");
    fs::create_dir_all(lua.join("prot"))?;
    publish_asset(&lua.join(CLIENT_PATH), BUNDLE, true)?;
    publish_asset(&lua.join("prot/router.lua"), LEGACY_ENTRY, false)
}

unsafe fn install_router(lua: State) -> Result<(), String> {
    if !lua.is_server() {
        return Err("prot: installation is server-only".into());
    }
    install_assets().map_err(|error| format!("prot: could not publish client Lua: {error}"))?;

    lua.get_global(lua_string!("AddCSLuaFile"));
    lua.push_string(CLIENT_PATH);
    if lua.pcall(1, 0, 0) != 0 {
        return Err(lua.get_string(-1).map_or_else(
            || "prot: AddCSLuaFile failed".into(),
            |error| error.into_owned(),
        ));
    }

    lua.load_buffer(BUNDLE.as_bytes(), lua_string!("@prot/embedded_router.lua"))
        .map_err(|error| format!("prot: {error:?}"))?;
    if lua.pcall(0, 0, 0) != 0 {
        return Err(lua.get_string(-1).map_or_else(
            || "prot: router startup failed".into(),
            |error| error.into_owned(),
        ));
    }
    Ok(())
}

#[lua_function]
unsafe fn install(lua: State) -> i32 {
    let top = lua.get_top();
    let result = install_router(lua);
    lua.set_top(top);
    match result {
        Ok(()) => {
            lua.push_boolean(true);
            1
        }
        Err(error) => {
            lua.push_nil();
            lua.push_string(&error);
            2
        }
    }
}

#[gmod13_open]
unsafe fn gmod13_open(lua: State) -> i32 {
    lua.new_table();
    lua.push_function(seed);
    lua.set_field(-2, lua_string!("Seed"));
    lua.push_function(install);
    lua.set_field(-2, lua_string!("Install"));
    lua.set_global(lua_string!("ProtNative"));
    0
}

#[gmod13_close]
fn gmod13_close(_: State) -> i32 {
    0
}
